/**
 * Shell — nptoy chrome: a thin config of the kit's AppShell (top bar, /command
 * bar, \ drawer, ? shortcuts, tab hotkeys). Generated by new-service.mjs; edit
 * TABS / status / labels here, fill the pages under src/pages/.
 */
import { useState, useEffect, useRef } from 'react'
import { AppShell, useLang, Avatar } from 'lilak-ui'
import { get, portalProfile, portalHome } from '../api'
import { ENABLED_THEMES } from '../theme/main'
import SettingsPage from '../pages/SettingsPage'
import FilesTab from '../g4/FilesTab.jsx'
import InputsTab from '../g4/InputsTab.jsx'
import SimulationTab from '../g4/SimulationTab.jsx'
import Community from './Community.jsx'

const TABS = [
  { id: "setup", icon: "home" },
  { id: "simulation", icon: "spinner" },
  { id: "files", icon: "folder" },
  { id: "community", icon: "community" },
  { id: "set", icon: "settings" },
]

// Simulation-session status shown in the top bar. Maps the backend session state
// (Geant4/nptool lifecycle) to a label + a dot colour readable on the orange bar.
const STATUS = {
  none:  { text: '대기',         dot: 'rgba(255,255,255,0.55)' },  // no live session
  boot:  { text: 'initializing', dot: '#ffe0b0' },                // start → G4 building geometry/physics
  init:  { text: 'initialized',  dot: '#ffe0b0' },                // ready at Idle>
  run:   { text: 'running',      dot: '#8ef0a6' },                // /run/beamOn in progress
  ended: { text: 'ended',        dot: '#bcd7ff' },                // a run finished (ready again)
  stop:  { text: 'stopped',      dot: '#ffb3ab' },                // session process gone
}
// `ever` = a session existed this page-view. User-stop removes the session (so
// /api/session returns null) — if one had existed, that null means "stopped",
// otherwise it's the initial "대기".
function statusKey(sess, ever) {
  if (!sess) return ever ? 'stop' : 'none'
  if (sess.state === 'starting') return 'boot'
  if (sess.state === 'running') return 'run'
  if (sess.state === 'stopped') return 'stop'
  if (sess.state === 'idle') return sess.runs > 0 ? 'ended' : 'init'
  return 'none'
}

export default function Shell() {
  const { t, lang } = useLang()
  const me = portalProfile()   // SSO profile — same identity as the portal + community
  const [tab, setTab] = useState("setup")
  const [sess, setSess] = useState(null)      // live simulation session (polled)
  const [proj, setProj] = useState({ name: '', run: null })  // setup name + next run number
  const everRef = useRef(false)               // a session has existed this page-view

  useEffect(() => {
    let alive = true
    const tick = async () => {
      try {
        const d = await get('/api/session')
        if (!alive) return
        if (d.session) everRef.current = true
        setSess(d.session)
      } catch { if (alive) setSess(null) }
    }
    tick()
    const id = setInterval(tick, 1000)
    return () => { alive = false; clearInterval(id) }
  }, [])

  const tabs = TABS.map((x) => ({ id: x.id, label: t('tab_' + x.id), icon: x.icon }))

  const st = STATUS[statusKey(sess, everRef.current)]
  // During a live session show its actual run number; otherwise the next run # that
  // a new run would use. Output files are {project}_{run}.{user}.sim.root.
  const runNo = sess?.run ?? proj.run
  const status = (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 10, fontSize: 'var(--fs-tiny, 11px)', color: 'var(--nav-text)' }}>
      {proj.name && <span style={{ fontWeight: 600 }}>{proj.name}</span>}
      {runNo != null && <span style={{ fontFamily: 'var(--font-mono)', opacity: 0.8 }}>#{runNo}</span>}
      <span style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontFamily: 'var(--font-mono)' }}>
        <span style={{ width: 6, height: 6, borderRadius: '50%', backgroundColor: st.dot }} />
        {st.text}
      </span>
    </span>
  )

  const labels = {
    help: t('cmd_help'), system: t('nav_system'), theme: t('set_theme'), language: t('set_lang'),
    account: t('nav_account'), notifications: t('notif_title'), command: t('cmd_placeholder'), shortcuts: t('shortcuts_title'),
  }

  const PAGES = {
    setup: <InputsTab onSetupName={setProj} />,
    simulation: <SimulationTab />,
    files: <FilesTab active={tab === 'files'} />,
    community: <Community />,
    set: <SettingsPage />,
  }

  return (
    <AppShell
      brand={lang === 'ko' ? t('brand') : 'lilak'}
      service={t('svc_name')}
      tabs={tabs}
      active={tab}
      onTab={setTab}
      themes={ENABLED_THEMES}
      status={status}
      labels={labels}
      commandBar={false}
      accountName={me.name}
      accountMeta={me.email}
      accountIcon={false}   /* top bar shows the id only (no avatar) */
      accountAvatar={<Avatar icon={me.shape} color={me.color} seed={me.email || me.name} size={46} />}
      onExit={() => { window.location.href = portalHome() }}
      exitLabel={t('exit_portal')}
    >
      {/* Keep every tab mounted (display toggle) so page state survives switches. */}
      {TABS.map(({ id }) => (
        <div key={id} style={{ height: '100%', display: tab === id ? 'block' : 'none' }}>{PAGES[id]}</div>
      ))}
    </AppShell>
  )
}
